QState motor_change_e(motor * const me) {
    /* New speed is not the actual speed (or substep counter is not zeor)
     * so update substepping parameters
     */
    compute_substep_param(me);

    /* Arm the timer */
    QTimeEvt_armX(&me->accel_timer, me->t_substp, me->t_substp);
    return QM_ENTRY(&motor_change_s);
}
