//${motor::motor::SM::operation::running::change}
QState motor_change(motor * const me, QEvt const * const e) {
    QState status_;
    switch (e->sig) {
        //${motor::motor::SM::operation::running::change::SPEED_REACHED}
        case SPEED_REACHED_SIG: {
            static struct {
                QMState const *target;
                QActionHandler act[2];
            } const tatbl_ = { // tran-action table
                &motor_cruise_s, // target state
                {
                    Q_ACTION_CAST(&motor_change_x), // exit
                    Q_ACTION_NULL // zero terminator
                }
            };
            status_ = QM_TRAN(&tatbl_);
            break;
        }
        //${motor::motor::SM::operation::running::change::MOTOR_STOPPED}
        case MOTOR_STOPPED_SIG: {
            static struct {
                QMState const *target;
                QActionHandler act[3];
            } const tatbl_ = { // tran-action table
                &motor_stop_s, // target state
                {
                    Q_ACTION_CAST(&motor_change_x), // exit
                    Q_ACTION_CAST(&motor_stop_e), // entry
                    Q_ACTION_NULL // zero terminator
                }
            };
            status_ = QM_TRAN(&tatbl_);
            break;
        }
        //${motor::motor::SM::operation::running::change::SPEED_TIMER}
        case SPEED_TIMER_SIG: {
            static QEvt const stopped = {MOTOR_STOPPED_SIG, 0u, 0u};
            static QEvt const cruise = {SPEED_REACHED_SIG, 0u, 0u};
            QEvt const * evt = NULL;
            uint16_t pwm = 0u;

            /* Change actual speed towards the desired speed cruise */
            /* 1. Acceleration or Deceleration? */
            if (SPEED_INCREASE == me->accel_dir) {
                me->substp_cnt++;
            } else {
                me->substp_cnt--;
            }

            /* 2. Compute PWM duty cycle */
            pwm = me->actual_pwm + ((me->substp_cnt * me->delta_pwm) >> me->substp_lsr);

            /* 3. And set it in the peripheral */
            motor_pwm_set(pwm, me->direction);

            /* 4. Integer speed reached? */
            if (((me->substp_cnt == me->substp_num) && (SPEED_INCREASE == me->accel_dir)) ||
                ((0u == me->substp_cnt) && (SPEED_DECREASE == me->accel_dir))) {

                /* 5. Update actual speed step */
                me->actual_step = me->next_step;

                /* 6. Target speed reached? */
                if (me->actual_step == me->target_step) {

                    /* 6A. Yes, send speed_reached/stopped signal */
                    if (0u == me->speed_table[me->actual_step]) {
                        evt = &stopped;
                    } else {
                        evt = &cruise;
                    }
                    QACTIVE_POST(ao_motor, evt, ao_motor);
                } else {

                    /* 6B. No, compute the parameters for next sub-stepping sequence*/
                    compute_substep_param(me);

                    /* 7. Re-arm the timer */
                    QTimeEvt_rearm(&me->accel_timer, me->t_substp);
                }
            }
            status_ = QM_HANDLED();
            break;
        }
        default: {
            status_ = QM_SUPER();
            break;
        }
    }
    return status_;
}

