//${motor::motor_ctor} .......................................................
uint32_t motor_ctor(void) {
    uint32_t res = NO_ERROR;

    motor * const me = &motor_inst;

    QMActive_ctor(&me->super, Q_STATE_CAST(&motor_initial));

    me->actual_step = 0u;
    me->target_step = 0u;
    me->next_step = 0u;
    me->direction = DIRECTION_FORWARD;
    me->accel_dir = MOTOR_ACCELERATION;

    QTimeEvt_ctorX(&me->accel_timer, ao_motor, SPEED_TIMER_SIG, TIMER_TICK_RATE);
    QTimeEvt_ctorX(&me->fault_timer, ao_motor, FAULT_TIMEOUT_SIG, TIMER_TICK_RATE);

    QEQueue_init(&me->zeroCrossingQueue, zcQueue, Q_DIM(zcQueue));

    QS_OBJ_DICTIONARY(ao_motor);

    QS_SIG_DICTIONARY(MOTOR_CONFIG_SIG, me);
    QS_SIG_DICTIONARY(MOTOR_CTRL_START_SIG, me);
    QS_SIG_DICTIONARY(MOTOR_CTRL_RECONFIGURE_SIG, me);
    QS_SIG_DICTIONARY(CHANGE_SPEED_SIG, me);
    QS_SIG_DICTIONARY(SET_SPEED_SIG, me);
    QS_SIG_DICTIONARY(EMERGENCY_BRAKE_SIG, me);
    QS_SIG_DICTIONARY(MOTOR_STOPPED_SIG, me);
    QS_SIG_DICTIONARY(SPEED_REACHED_SIG, me);
    QS_SIG_DICTIONARY(SPEED_TIMER_SIG, me);

    return res;
}
